 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture as tslTexture, color as tslColor } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DoubleSide, SRGBColorSpace } = ctx.THREE;

  const group = new Group();
  group.userData.handlers = {};

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const timelines = [];
  const textures = [];
  let cleaned = false;

  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide
  });
  material.colorNode = tslColor(colors.surface);

  const plane = new Mesh(geometry, material);
  group.add(plane);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      if (cleaned) {
        tex.dispose();
        return;
      }
      textures.push(tex);
      material.colorNode = tslTexture(tex);
      material.needsUpdate = true;
    });
  }

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || !item.text) continue;
    const textObj = ctx.fontAtlas.createText(String(item.text), {
      fontSize: item.typography?.fontSize ?? 39,
      color: colors.paper,
      align: 'center'
    });
    textObj.position.z = 0.03;
    group.add(textObj);
  }

  group.userData.cleanup = () => {
    cleaned = true;
    for (const tl of timelines) {
      if (tl && typeof tl.kill === 'function') tl.kill();
    }
    for (const tex of textures) {
      tex.dispose();
    }
    geometry.dispose();
    material.dispose();
  };

  return group;
}
